export const nexusPositionMonitor = async () => {
  while (true) {
    const position = await fetchPositionData(positionId);
    const health = calculateHealthFactor(position);

    if (health < 1.05) {
      // CRITICAL: Auto-trigger Yellow Network boost
      await triggerYellowBoost(positionId);
